CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,password_hash TEXT NOT NULL,verified INTEGER NOT NULL DEFAULT 0 CHECK(verified IN(0,1)),created_at TEXT NOT NULL);
CREATE TABLE workspaces(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at INTEGER NOT NULL);
CREATE TABLE account_tokens(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),purpose TEXT NOT NULL CHECK(purpose IN('verify','recover')),expires_at INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE rate_limits(bucket TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE projects(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),owner_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL CHECK(length(title) BETWEEN 1 AND 300),language TEXT NOT NULL,direction TEXT NOT NULL CHECK(direction IN('auto','ltr','rtl')),version TEXT NOT NULL,access_epoch INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE project_memberships(project_id TEXT NOT NULL REFERENCES projects(id),user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN('owner','editor','viewer')),PRIMARY KEY(project_id,user_id));
CREATE TABLE manuscripts(id TEXT PRIMARY KEY,project_id TEXT NOT NULL UNIQUE REFERENCES projects(id),schema_version INTEGER NOT NULL DEFAULT 2);
CREATE TABLE chapters(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),title TEXT NOT NULL,position INTEGER NOT NULL,current_revision_id TEXT,UNIQUE(project_id,id),FOREIGN KEY(id,current_revision_id) REFERENCES chapter_revisions(chapter_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE chapter_revisions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,chapter_id TEXT NOT NULL,sequence INTEGER NOT NULL CHECK(sequence>0),ast_json TEXT NOT NULL,sha256 TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id),restored_from TEXT REFERENCES chapter_revisions(id),created_at TEXT NOT NULL,UNIQUE(chapter_id,sequence),UNIQUE(chapter_id,id),FOREIGN KEY(project_id,chapter_id) REFERENCES chapters(project_id,id));
CREATE TRIGGER immutable_revisions_update BEFORE UPDATE ON chapter_revisions BEGIN SELECT RAISE(ABORT,'revisions are immutable'); END;
CREATE TRIGGER immutable_revisions_delete BEFORE DELETE ON chapter_revisions BEGIN SELECT RAISE(ABORT,'revisions are immutable'); END;
CREATE TABLE manuscript_versions(id TEXT PRIMARY KEY,manuscript_id TEXT NOT NULL REFERENCES manuscripts(id),manifest_json TEXT NOT NULL,sha256 TEXT NOT NULL,created_at TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id));
CREATE TABLE command_receipts(actor_id TEXT NOT NULL REFERENCES users(id),operation TEXT NOT NULL,resource TEXT NOT NULL,command_key TEXT NOT NULL,request_hash TEXT NOT NULL,response_json TEXT NOT NULL,PRIMARY KEY(actor_id,operation,resource,command_key));
CREATE TABLE conversion_jobs(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),actor_id TEXT NOT NULL REFERENCES users(id),source_version_id TEXT NOT NULL REFERENCES manuscript_versions(id),format TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('queued','running','validating','succeeded','failed')),input_hash TEXT NOT NULL,artifact_id TEXT,error_code TEXT,created_at TEXT NOT NULL);
CREATE TABLE export_artifacts(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),job_id TEXT NOT NULL UNIQUE REFERENCES conversion_jobs(id),media_type TEXT NOT NULL,filename TEXT NOT NULL,content BLOB NOT NULL,sha256 TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE audit_events(id TEXT PRIMARY KEY,actor_id TEXT,action TEXT NOT NULL,resource_id TEXT NOT NULL,metadata_json TEXT NOT NULL,previous_hash TEXT NOT NULL,event_hash TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TRIGGER immutable_audit_update BEFORE UPDATE ON audit_events BEGIN SELECT RAISE(ABORT,'audit events are append only'); END;
CREATE TRIGGER immutable_audit_delete BEFORE DELETE ON audit_events BEGIN SELECT RAISE(ABORT,'audit events are append only'); END;
CREATE TABLE outbox(id TEXT PRIMARY KEY,event_type TEXT NOT NULL,schema_version INTEGER NOT NULL,aggregate_id TEXT NOT NULL,payload_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX membership_user ON project_memberships(user_id,project_id);
CREATE INDEX chapter_order ON chapters(project_id,position);
CREATE INDEX history ON chapter_revisions(chapter_id,sequence DESC);
CREATE INDEX session_expiry ON sessions(expires_at);
CREATE INDEX project_updated ON projects(workspace_id,updated_at DESC);
CREATE INDEX job_project ON conversion_jobs(project_id,created_at);
CREATE TABLE import_previews(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),actor_id TEXT NOT NULL REFERENCES users(id),filename TEXT NOT NULL,original BLOB NOT NULL,ast_json TEXT NOT NULL,warnings_json TEXT NOT NULL,report_hash TEXT NOT NULL,confirmed_chapter_id TEXT REFERENCES chapters(id),created_at TEXT NOT NULL);

CREATE TRIGGER immutable_artifacts_update BEFORE UPDATE ON export_artifacts BEGIN SELECT RAISE(ABORT,'artifacts are immutable'); END;
CREATE TRIGGER immutable_artifacts_delete BEFORE DELETE ON export_artifacts BEGIN SELECT RAISE(ABORT,'artifacts are immutable'); END;
